/* Calendar */
mk('viewCalendar',H('cal','Calendar','📆 Calendar · November 2026','Past failures, repeat occurrences, upcoming expiries and journey runs on one month view. Click a day to see what happened or what is coming.')+`<section class="x-grid2" style="grid-template-columns:2fr 1fr"><div class="panel glass"><div class="cal" id="calG"></div></div><div class="panel solid"><h4 id="calH">Today</h4><div id="calD"></div></div></section>`);
function calEvents(){const E={};const add=(d,t,c,k)=>{(E[d]=E[d]||[]).push({t,c,k})};
 Object.entries(HIST).forEach(([c,h])=>h.forEach(o=>{const dt=D(o.d);if(dt.getMonth()===10)add(dt.getDate(),`🔁 ${ERR[c].t} · ${o.bu}`,ERR[c].c,c)}));
 INC.forEach(i=>add(16,`⛔ ${ERR[i.code].t} · ${i.recs}`,ERR[i.code].c,i.code));
 [[14,'⏳ SG voucher def expired','#FF453A'],[22,'⏳ TH Black Birthday def expires','#FF9F0A'],[23,'⏳ Tier Black ends · 214 MY','#FF9F0A'],[23,'⏳ Escrow release SSMY…1133','#BF5AF2'],[27,'⏳ MY Points bonus def expires','#FFD60A'],[30,'📋 Month-end tier batch','#0A84FF']].forEach(([d,t,c])=>add(d,t,c));
 for(let d=17;d<=30;d++)add(d,`🧭 ${10+(d%4)} journeys scheduled`,'#30D158');return E}
RENDER.calendar=function(){const E=calEvents();const first=new Date(2026,10,1).getDay();let h=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="dh">${d}</div>`).join('');
 for(let i=0;i<first;i++)h+=`<div class="d mute"></div>`;for(let d=1;d<=30;d++){const ev=E[d]||[];h+=`<div class="d ${d===16?'today':''}" onclick="x_calDay(${d})"><span class="n">${d}</span>${ev.slice(0,3).map(e=>`<span class="ev2" style="background:${e.c}2e;color:var(--text)">${esc(e.t)}</span>`).join('')}${ev.length>3?`<span class="ev2" style="color:var(--muted)">+${ev.length-3} more</span>`:''}</div>`}
 $('#calG').innerHTML=h;window._calE=E;x_calDay(16)};
window.x_calDay=d=>{const ev=(window._calE||{})[d]||[];$('#calH').textContent=`${d} November 2026${d===16?' · today':''}`;$('#calD').innerHTML=ev.map(e=>`<div class="conf2" style="cursor:${e.k?'pointer':'default'}" ${e.k?`onclick="x_openInc('${e.k}')"`:''}><div><b style="font-size:12.5px">${esc(e.t)}</b></div><span style="width:10px;height:10px;border-radius:50%;background:${e.c};align-self:center"></span></div>`).join('')||'<div class="empty"><div class="ic">🌤</div>Nothing on this day</div>'};

/* Wins */
mk('viewWins',H('wn','Wins','🏆 Wins','The good news: clean-run streaks, issues closed and milestones. A quick way to see progress, not just problems.')+`<section class="x-kpis" id="wnK"></section><section class="x-grid2"><div class="panel solid"><h4>✅ Issues closed per day <small>last 14 days</small></h4><div id="wnC"></div></div><div class="panel solid"><h4>🔥 Clean-run streaks</h4><div id="wnS"></div></div></section><section class="panel glass"><h4>🎖 Badges</h4><div class="rep-cards" style="grid-template-columns:repeat(auto-fill,minmax(160px,1fr))" id="wnB"></div></section>`);
RENDER.wins=function(){$('#wnK').innerHTML=kpiH('Closed today',127,'+41 vs 7-day avg','ok')+kpiH('Closed this week',612,'best week this month','ok')+kpiH('Longest streak',7,'HK 5090 clean runs','ok')+kpiH('Recovered journeys',1,'TH AT Welcome','ok')+kpiH('Tasks done',TASKS.filter(t=>t[2]).length,'from My Day','ok');countAll($('#wnK'));
 const c=[60,70,80,86,90,100,127,64,72,95,88,101,110,127];$('#wnC').innerHTML=barChart(c.map(v=>({p:v,c:0})),{h:200,stack:[['p','#30D158','Closed']],labels:Array.from({length:14},(_,i)=>(3+i)+' Nov')});
 $('#wnS').innerHTML=[['HK 5090',7],['TW 5060',4],['JP 5630',3],['TUMI',3],['Warranty',2],['SG 5010',0]].map(([n,s])=>`<div class="tierrow" style="grid-template-columns:110px 1fr 70px"><span>${n}</span><span class="t"><i style="width:${s/7*100}%;background:linear-gradient(90deg,#FF9F0A,#FF453A)"></i></span><b>${s?'🔥 '+s:'— broken'}</b></div>`).join('');
 $('#wnB').innerHTML=[['🔥','7-run streak','HK 5090',1],['🧹','100 closed in a day','16 Nov',1],['🛫','First STOP caught','pre-flight',1],['🔁','Repeat broken','fix held 14 days',0],['🏁','All markets grade A','keep going',0],['🌟','Zero failures day','not yet',0]].map(([e,n,s,u])=>`<div class="badge3 glass ${u?'':'locked'}"><span class="e">${e}</span><b>${n}</b><small>${s}</small></div>`).join('')};

/* Logs */
mk('viewLogs',H('lg','Logs','🧾 Run logs','What the agent did, line by line: pre-flight checks, read-only queries, exports and alerts. Use it to see exactly when and why something failed. Nothing here writes to Prod.')+`<section class="panel glass"><div class="toolbar"><input class="inp" id="lgQ" placeholder="Filter logs…" style="flex:1"><span class="chips" id="lgF"><span class="chip on" data-f="">All</span><span class="chip" data-f="E">Errors</span><span class="chip" data-f="W">Warnings</span><span class="chip" data-f="I">Info</span></span><button class="btn ghost sm" onclick="x_copy(encodeURIComponent(document.getElementById('lgV').innerText),'logs')">⧉ Copy</button></div><div class="logv" id="lgV"></div></section>`);
const LOGS=(()=>{const L=[];const add=(t,k,m)=>L.push([t,k,m]);add('06:30:00','I','scheduler: SAM/AT set started (mode=read-only)');add('06:30:01','O','preflight: sf org display -o SFLM_upd_Prod → Connected');add('06:30:02','I','preflight: disk free 41 GB · VJ script present');
 J.forEach((j,i)=>{const t=`06:${String(31+i).padStart(2,'0')}:${String(10+i).padStart(2,'0')}`;add(t,'I',`journey-monitor: ${j.n} (${j.bu}) – SELECT journey activity log … ${fmt(j.in)} rows`);Object.entries(j.err).forEach(([c,n])=>add(t,c==='E_CONSENT'?'W':'E',`journey-monitor: ${j.n} – ${n} × ${c} (${ERR[c].t})`))});
 add('06:52:40','W','export: TW 5060 bulk export retry 1/3 (HTTP 503)');add('06:53:12','O','export: TW 5060 bulk export OK · 182,004 rows');add('06:55:00','I','rca: 7 root causes clustered · 627 records');add('06:55:01','I','notify: bell + toast sent (3 SEV-1)');
 UP.forEach(u=>add('07:00:00',u.verdict==='stop'?'E':u.verdict==='warn'?'W':'O',`preflight: ${u.j.n} @${u.t} – ${VLAB[u.verdict]} · predicted fail ${u.fail}/${u.aud}`));add('07:00:05','O','scheduler: run finished · report written reports/Sam & AT_Report_2026-11-16_sam.md');return L})();
let lgf='';function lgDraw(){const q=($('#lgQ').value||'').toLowerCase();$('#lgV').innerHTML=LOGS.filter(l=>(!lgf||l[1]===lgf||(lgf==='I'&&l[1]==='O'))&&(!q||l[2].toLowerCase().includes(q))).map(l=>`<div class="${l[1]}">${l[0]}  ${{E:'ERROR',W:'WARN ',I:'INFO ',O:'OK   '}[l[1]]}  ${esc(l[2])}</div>`).join('')}
RENDER.logs=function(){$('#lgQ').oninput=lgDraw;$$('#lgF .chip').forEach(c=>c.onclick=()=>{$$('#lgF .chip').forEach(x=>x.classList.remove('on'));c.classList.add('on');lgf=c.dataset.f;lgDraw()});lgDraw()};

/* ---------- navigation wiring ---------- */
const NEWV={repeats:['viewRepeats','Repeat issues'],schedule:['viewSchedule','Schedule'],reports:['viewReports','Reports'],myday:['viewMyday','My Day'],board:['viewBoard','Tracker board'],following:['viewFollowing','Following'],calendar:['viewCalendar','Calendar'],wins:['viewWins','Wins'],logs:['viewLogs','Logs']};
Object.entries(NEWV).forEach(([k,[id,n]])=>{VIEWS[k]=id;NAVN[k]=n;CR[k]=n});
const ul=document.querySelector('#g0 .nav');let af=[...ul.children].find(li=>li.dataset.n==='Pre-flight');
[['Schedule','🗓','schedule',''],['Repeat issues','🔁','repeats',String(Object.keys(HIST).length),1]].forEach(([n,e,v,b,hot])=>{const li=document.createElement('li');li.dataset.n=n;li.tabIndex=0;li.innerHTML=`<span style="width:18px;text-align:center;flex:none">${e}</span><span class="nav-label">${n}</span>${b?`<span class="badge ${hot?'':'soft'}">${b}</span>`:''}`;li.onclick=()=>x_show(v);ul.insertBefore(li,af.nextSibling);af=li});
const MAP={'Reports':'reports','Logs':'logs','Batches':'schedule','Findings':'records','Daily summary':'reports','My Day':'myday','Tracker board':'board','Following':'following','Calendar':'calendar','Wins':'wins'};
$$('.nav li').forEach(li=>{const v=MAP[li.dataset.n];if(v)li.addEventListener('click',()=>{x_show(v);if(li.dataset.n==='Daily summary')setTimeout(()=>x_report('daily'),400)})});
PITEMS.push(...Object.entries(NEWV).map(([k,[,n]])=>({n,s:'page',f:()=>x_show(k)})),...REPORTS.map(r=>({n:r[2],s:'report',f:()=>{x_show('reports');setTimeout(()=>x_report(r[0]),350)}})));

