 viewInsights:['Insights','Is it getting better or worse?',[['Market × cause matrix','Darker cells mean more records. Click a cell for the records.'],['Pareto','The few causes behind most of the failures.'],['Trends','Failure rate by week and failed records by day.'],['Digest','A ready-made summary to paste into Teams or email.']]],
 viewFolders:['Folders','The result folders for every market and check, grouped on shelves. Click a folder to open its details and records.',[]],
 viewReports:['Reports','Ready-made reports. Open one, then copy it as CSV for Excel.',[['Daily failures','The day\'s journey results.'],['Root cause, repeats, market scorecard','For reviews and follow-ups.'],['Pre-flight, owner actions, SLA','For planning and chasing teams.']]],
 viewMyday:['My Day','Your checklist. Add tasks, set a priority and tick them off. The agent suggests tasks from today\'s problems. Saved in your browser only.',[]],
